{
  "headline": "Vasopressin is not on FDA's shortage list; Corvale East has 36.7 days and Corvale General 29.3 days on hand; top alternate is Dr. Reddy's Laboratories, Inc. with plant VAI 2024-05-17",
  "headline_cites": ["D3", "D1", "D2", "D4"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows vasopressin is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 161 vials of the 1 mL presentation with 4.4 vials used per day, giving 36.7 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 185 vials with 6.3 vials used per day, giving 29.3 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The rule ranks Dr. Reddy's Laboratories, Inc. as the first alternate manufacturer; its plant Dr. Reddy's Laboratories Limited-FTO-9 was last inspected VAI on 2024-05-17.",
      "cites": ["D4"]
    },
    {
      "text": "American Regent, Inc. is the second alternate with a plant last inspected VAI on 2026-06-18.",
      "cites": ["D5"]
    },
    {
      "text": "Amneal Pharmaceuticals LLC is the third alternate but its label names no plant we could place.",
      "cites": ["D6"]
    },
    {
      "text": "The current label for the product in use names Medical Purchasing Solutions, LLC (FEI 3014288534), a registered repack plant last inspected VAI on 2024-09-11.",
      "cites": ["E4", "E3"]
    }
  ]
}
